INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('4eb1c40e-1b7e-4d15-ae85-e3a36d6efe38','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'delete','studio_world_records','fa7dca29-383c-4452-8757-cf2bc3678f30','Bone Dragon / Hybrid Elemental Dragon
Parentage: Terrax + Leviathans
Important family relationships: Son of Terrax and Leviathans; protective older brother of Ife; related to Rahim, Gaius and Shailara through shared parents.
Primary element/power: Bone — synthesis of Earth and Water.
Signature appearance: Long black hair, warm brown complexion, amber-gold eyes, ivory living bone armor and Indian-inspired clothing.','{"workflow_status":"draft"}','2026-09-25T07:27:57.150437+00:00');
INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('aec1d64f-bcf9-4215-beaa-4d9a49201fd9','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'delete','studio_world_records','3d095ec9-656f-4065-acb9-e1b3fecf35bc','Family is something one actively maintains.
Love: Love is demonstrated through action.
Death: Even the strongest structure eventually returns to the world.
Magic: Magic should be understood before it is wielded recklessly.
Religion/spirituality: TBD.
Authority: Respect should be earned.
Strength: True strength is the ability to endure without abandoning responsibility.
Weakness: Weakness is not failure; refusing to acknowledge damage is dangerous.
Good and evil: Actions matter more than titles.','{"workflow_status":"draft"}','2026-09-25T07:27:59.117905+00:00');
INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('342b2dc5-8919-456e-aef4-1f9b0d4cb1e7','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'update','studio_characters','f1a92df4-a271-4f90-beb5-662c725b2661','Mvula','{"workflow_status":"draft"}','2026-09-25T07:30:52.506724+00:00');
INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('52cfd104-db47-45c5-ad22-b740b43f0c93','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'insert','studio_world_records','34a82db4-0c9b-4781-bfe6-b02158c3bc16','Ignis Peaks — born into the elemental bloodlines of Fire and Water, with ancestral ties to both the Ignis Peaks and the Sunken Dominion.','{"workflow_status":"draft"}','2026-09-25T07:31:22.586136+00:00');
INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('ae32310e-9fc0-4917-9bd2-dd3099dd2da4','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'insert','studio_world_records','6be96aa6-c600-4eb2-838f-858537bd5385','Ignis Peaks — born into the elemental bloodlines of Fire and Water, with ancestral ties to both the Ignis Peaks and the Sunken Dominion.','{"workflow_status":"draft"}','2026-09-25T07:31:22.716959+00:00');
INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('ebf254c9-9b73-4a8b-a49f-f2868c18fedc','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'insert','studio_world_records','f3e8fc47-10f0-4ea5-8913-2b741e0c1739','Primordial Elemental Lineage  Paternal Element: Fire  Maternal Element: Water  Personal Element: Steam  Ife represents a successful equilibrium between opposing Primordial forces.  Her existence demonstrates that Primordial elements do not necessarily produce a simple mixture when combined through descendants.  Instead, their children can develop entirely new elemental expressions.  For Ife:  Fire + Water → Steam  Steam therefore belongs specifically to her elemental identity.  She did not inherit half of Ignis''s fire abilities and half of Leviathans'' water abilities.  Their elemental principles fused and became something new.','{"workflow_status":"draft"}','2026-09-25T07:31:22.805365+00:00');
